# Analyze each changed example
inputs = ['jefv', 'hxu', 'cdceci', 'ykdfcd', 'fdj']
outputs = ['aefv', 'hxu', 'cxceci', 'yxwbxfcx', 'wa']

# Let's look at the differences more carefully
examples = [
    ('jefv', 'aefv'),    # j->a
    ('cdceci', 'cxceci'), # d->x  
    ('ykdfcd', 'yxwbxfcx'), # yk->yx, df->wb, cd->xf
    ('fdj', 'wa')         # fd->wa
]

print("Detailed analysis:")
for i, (inp, outp) in enumerate(examples):
    print(f"Example {i}: '{inp}' -> '{outp}'")

    # Find character-by-character differences
    min_len = min(len(inp), len(outp))
    diff_positions = []
    for j in range(min_len):
        if inp[j] != outp[j]:
            diff_positions.append((j, inp[j], outp[j]))

    if len(inp) != len(outp):
        if len(inp) > len(outp):
            for j in range(min_len, len(inp)):
                diff_positions.append((j, inp[j], None))
        else:
            for j in range(min_len, len(outp)):
                diff_positions.append((j, None, outp[j]))

    print(f"  Differences: {diff_positions}")
    print()

